using MbyteWeb.Server.Authorization; using MbyteWeb.Server.Data; using MbyteWeb.Server.Helpers; using MbyteWeb.Server.ViewModels.Admin.RegistroAuditoria; using Microsoft.AspNetCore.Mvc;
namespace MbyteWeb.Server.Controllers;
[Route("api/auditoria")][ApiController][HasPermission(PermisosEnum.Auditoria)] public class RegistroAuditoriasController(AppDbContext context) : ControllerBase { [HttpGet] public async Task<ActionResult> GetAll([FromQuery] RegistroAuditoriasQuery query) { var result = FilterBuilder.Create(context.RegistroAuditorias.AsQueryable()).Between(item => item.Fecha, query.Desde, query.Hasta).Eq(item => (int)item.TipoAuditoria, query.TipoAuditoria).Contains(item => item.NombreTabla, query.NombreTabla).Contains(item => item.NombreUsuario, query.NombreUsuario).Contains(item => item.ColumnasAfectadas, query.ColumnasAfectadas).Contains(item => item.ClavePrimaria, query.ClavePrimaria).ToQuery(); if (!string.IsNullOrWhiteSpace(query.ExcludeTablas)) { var excluded = query.ExcludeTablas.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries); result = result.Where(item => !excluded.Contains(item.NombreTabla)); } return Ok(await QueryResponseBuilder.Create(result.OrderByDescending(item => item.Fecha), query.Page, query.PageSize)); } }
